#!/usr/bin/env bash
# The ElastiCORE plugin's hooks. They keep an agent on the DSL side of an
# ElastiCORE project: a generated file is changed through the YAML under
# src/main/resources/blueprint, and a DSL change is generated and compiled
# before the agent says it is done.
#
#   pre-edit   PreToolUse  Edit|Write|MultiEdit  refuse an edit to a file the generator manages
#   post-edit  PostToolUse Edit|Write|MultiEdit  after a DSL edit, say what to run before finishing
#   post-bash  PostToolUse Bash                  after a Gradle run, report the generator's warnings
#   stop       Stop                              do not finish while a DSL change has not been built
#
# Bash and POSIX tools only: Claude Code runs hooks with sh on macOS and Linux
# and with Git Bash on Windows. Anything unexpected ends in exit 0 or 1, which
# lets the action go ahead - a broken hook never blocks the user's work.
#
# ELASTICORE_ALLOW_GENERATED_EDITS=1 lets edits to generated files through.

set -u

event="${1:-}"
input="$(cat)" || exit 0

# The raw value of a JSON string field, still escaped. Claude Code sends one
# line of JSON; a key inside another string value is escaped (\"key\") and is
# not matched.
json_string() {
    printf '%s' "$input" | sed -nE 's/.*"'"$1"'"[[:space:]]*:[[:space:]]*"((\\.|[^"\\])*)".*/\1/p' | head -n 1
}

# The edited file. Windows paths arrive as C:\\dir\\file; Git Bash reads them
# with forward slashes, and slashes keep them safe inside the JSON written below.
file_path() {
    json_string file_path | sed 's#\\\\#/#g'
}

# Who owns a file, from its first lines - the rules the generator itself applies.
#   none     no such file yet
#   hand     not written by ElastiCORE
#   owned    "Initially generated by ElastiCORE": the developer's
#   block    generated, with a preserved block that survives regeneration
#   managed  generated: rewritten from the DSL
classify() {
    [ -f "$1" ] || { echo none; return; }
    first="$(head -n 1 -- "$1" 2>/dev/null | tr -d '\r')"
    case "$first" in
        //ecd:*) ;;
        *) echo hand; return ;;
    esac
    if head -c 600 -- "$1" 2>/dev/null | grep -q 'Initially generated by ElastiCORE'; then
        echo owned
    elif grep -q -F -e '// !----------' -- "$1" 2>/dev/null; then
        echo block
    else
        echo managed
    fi
}

is_dsl() {
    case "$1" in
        */src/main/resources/blueprint/*.yml | */src/main/resources/blueprint/*.yaml) return 0 ;;
    esac
    return 1
}

# Text for a JSON string: one line, quotes and backslashes escaped.
json_text() {
    printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'
}

# Context for Claude: after a tool ran, or as the reason to go on instead of
# stopping. Unlike exit 2, the transcript shows it as feedback, not an error.
context() {
    printf '{"hookSpecificOutput":{"hookEventName":"%s","additionalContext":"%s"}}\n' "$1" "$(json_text "$2")"
}

# Refuse a tool call; Claude reads the reason.
deny() {
    printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"deny","permissionDecisionReason":"%s"}}\n' "$(json_text "$1")"
}

# A note that this session changed the DSL and no build has generated from it
# since. One file per session, in the plugin's data directory.
state_dir="$(printf '%s' "${CLAUDE_PLUGIN_DATA:-${TMPDIR:-/tmp}/elasticore-agent-kit}" | tr '\\' '/')"
session="$(json_string session_id | tr -cd 'A-Za-z0-9_-')"
marker="$state_dir/dsl-changed-${session:-default}"

case "$event" in

pre-edit)
    [ "${ELASTICORE_ALLOW_GENERATED_EDITS:-}" = 1 ] && exit 0
    path="$(file_path)"
    [ -n "$path" ] || exit 0
    if [ "$(classify "$path")" = managed ]; then
        deny "ElastiCORE generates $path from the DSL (its first line is //ecd:). A hand edit is not kept in step: from the next build on, the generator skips the file - SKIP(user-modified) - and it no longer follows the DSL. Make this change in the YAML under src/main/resources/blueprint, or in a file that carries the line 'Initially generated by ElastiCORE' - the elasticore skill says which. If the user wants this generated file edited by hand anyway, they can set ELASTICORE_ALLOW_GENERATED_EDITS=1."
    fi
    exit 0
    ;;

post-edit)
    path="$(file_path)"
    [ -n "$path" ] || exit 0
    if is_dsl "$path"; then
        if [ ! -f "$marker" ]; then
            mkdir -p -- "$state_dir" 2>/dev/null && : > "$marker"
            context PostToolUse "You changed the ElastiCORE DSL. Before you finish, run ./gradlew compileJava - it regenerates first - and fix every line under 'DSL validation warnings:' and every compile error, in the DSL. Read the generator's SKIP(...) lines too."
        fi
        exit 0
    fi
    if [ "$(classify "$path")" = block ]; then
        context PostToolUse "$path is generated by ElastiCORE. Only code between '// !----------' and '// ------------!' survives regeneration; anything changed outside that block belongs in the DSL."
    fi
    exit 0
    ;;

post-bash)
    case "$input" in *gradle*) ;; *) exit 0 ;; esac
    command="$(json_string command)"
    printf '%s' "$command" | grep -Eq 'gradlew?(\.bat)?([^A-Za-z0-9_.-]|$)' || exit 0
    printf '%s' "$command" | grep -Eq '(^|[[:space:]:])(elcore[A-Za-z0-9]*|compileJava|compileKotlin|classes|processResources|build|assemble|bootRun|test|check|jar|bootJar)([[:space:]]|$)' || exit 0

    # What Gradle printed. The command itself may name the same words (a grep),
    # so only the tool's response counts.
    output="$(printf '%s' "$input" | sed -n 's/.*"tool_response"//p')"
    note=""
    if printf '%s' "$output" | grep -qi 'DSL validation warnings'; then
        note="The ElastiCORE generator listed DSL validation warnings. The build succeeds anyway, but the model is wrong until they are gone: fix each line under that header in the DSL and run the build again. "
    fi
    if printf '%s' "$output" | grep -q -e 'SKIP(user-modified' -e 'User-Modified Files'; then
        note="${note}Generated files were edited by hand, so the generator skipped them. Move those changes into the DSL or into a file you own, then restore each file by deleting it and generating again. Do not use -Pforce without asking the user."
    fi
    if [ -z "$note" ] && ! printf '%s' "$output" | grep -q 'BUILD FAILED'; then
        rm -f -- "$marker"
    fi
    [ -n "$note" ] && context PostToolUse "$note"
    exit 0
    ;;

stop)
    printf '%s' "$input" | grep -Eq '"stop_hook_active"[[:space:]]*:[[:space:]]*true' && exit 0
    [ -f "$marker" ] || exit 0
    # Remind once per DSL change; the next DSL edit sets the note again.
    rm -f -- "$marker"
    context Stop "The ElastiCORE DSL changed in this session and no Gradle build has generated from it since. Run ./gradlew compileJava - it regenerates first - and fix every DSL validation warning and compile error before you finish. If the user asked you not to build, say so in your answer instead."
    exit 0
    ;;

esac
exit 0
